from pathlib import Path
import importlib.util
HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('bounded_author',HERE.parent/'wirtschaft-e2-twenty-bilingual-positive-author-v1/author_candidate.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);m.OUT=HERE;m.REVIEW_ID='canonical-economics-q3-trade-finance-sixteen-positive-author-20261008-v1';m.REVIEWER='codex-economics-q3-trade-finance-sixteen-author-v1';m.ENTRIES=[]
def add(title,description,archetype,de,en,ode,oen,cases,axes):m.add(title,description,archetype,(de,en,ode,oen),cases,axes)
add('Evaluate tariff and trade policy','The learner can weigh instruments between protectionism and free trade.','concept',
 'Zölle, Mengenbegrenzungen und Marktöffnung verändern Preise, Auswahl und Wettbewerb verschieden. Abwägen verknüpft ein konkretes Ziel mit Folgen für Betroffene, Kosten und Alternativen; ein Nutzen für eine Branche ist kein sicherer gesamtwirtschaftlicher Vorteil.',
 'Tariffs, quantity restrictions and market opening affect prices, choice and competition differently. Weighing policies connects an objective to effects on groups, costs and alternatives; a benefit to one industry is not necessarily an economy-wide gain.',
 'Die Person wägt in neuen Fällen mindestens zwei gegebenen handelspolitischen Optionen anhand offener Kriterien, Wirkungen und Bedingungen begründet ab.',
 'In new cases, the learner weighs at least two supplied trade-policy options through explicit criteria, mechanisms and conditions.',
 [('import-tariff-or-adjustment','Ein fiktiver Staat möchte eine heimische Branche stabilisieren. Importpreis50, heimische Stückkosten70; Optionen sind ein Zoll10 oder befristete Anpassungshilfe bei offenem Handel. Material nennt Beschäftigung, Verbraucher und Finanzierung. Wäge ab.',
   'A fictional state wants to stabilise a domestic industry. The import price is50, domestic unit cost70; options are a tariff10 or temporary adjustment support with open trade. Materials give employment, consumers and financing. Weigh them.',
   'Die Person erklärt den Importpreis60 bei vollständiger Weitergabe und verbleibenden Kostenabstand10. Sie wägt Schutz, Verbraucherbelastung und Anpassungshilfe mit Finanzierung ab, ohne gesicherte Jobs oder globale Vorteile allein aus dem Zoll abzuleiten.',
   'The learner explains an import price60 under full pass-through and a remaining cost gap10. They weigh protection, consumer burdens and adjustment support with funding, without inferring guaranteed jobs or aggregate gains from the tariff alone.',
   'Schutzinstrument und gezielte Alternative am Ziel prüfen.','Examine protection and a targeted alternative against the objective.'),
  ('quota-or-mutual-recognition','Ein anderer fiktiver Markt hat Lieferengpässe und doppelte Prüfkosten. Optionen sind eine Importquote oder gegenseitige Anerkennung ausdrücklich gleichwertiger Sicherheitsprüfungen. Material nennt Versorgung, heimische Anbieter und Kontrollkosten. Wäge ab.',
   'Another fictional market has supply shortages and duplicate testing costs. Options are an import quota or mutual recognition of explicitly equivalent safety tests. Materials give supply, domestic firms and control costs. Weigh them.',
   'Die Person vergleicht Mengenbegrenzung und Kostensenkung bei gleicher Sicherheit, berücksichtigt Knappheit, Wettbewerb und Kontrolle und begründet ein bedingtes Urteil. Sie bezeichnet weder jede Norm als Protektionismus noch freien Handel als kostenfrei.',
   'The learner compares quantity limits with cost reductions at equal safety, considers shortages, competition and controls, and gives a conditional judgment. They label neither every standard protectionism nor free trade costless.',
   'Ziel, Legitimität und unterschiedliche Instrumentenwirkung.','Objectives, legitimacy and different policy mechanisms.')],
 [('policy-target','Beschäftigung, Versorgung, Anpassung oder Sicherheitsniveau.','Employment, supply, adjustment or safety.'),('instrument-conditions','Weitergabe von Zöllen, Mengenknappheit und Vergleichbarkeit von Standards.','Tariff pass-through, quantity scarcity and equivalent standards.')])
add('Discuss financial-market regulation','The learner can explain regulation and crisis mechanisms in the global financial system.','concept',
 'Finanzkrisen können über Verluste, hohe Verschuldung, kurzfristige Finanzierung und Verflechtungen verstärkt werden. Kapital-, Liquiditäts- oder Transparenzregeln setzen an unterschiedlichen Mechanismen an; einzelne Regeln beseitigen nicht jedes Risiko.',
 'Financial crises can be amplified by losses, leverage, short-term funding and interconnections. Capital, liquidity or disclosure rules address different mechanisms; one rule does not remove every risk.',
 'Die Person erklärt neue internationale Krisenketten und ordnet mehrere passende Regulierungsmechanismen mit ihrer jeweiligen Grenze zu.',
 'The learner explains new international crisis chains and matches several appropriate regulatory mechanisms with their limits.',
 [('leveraged-cross-border-loss','Ein vereinfachtes fiktives Banknetz hält Aktiva100, Fremdkapital95 und Eigenkapital5. Verluste8 treffen eine Bank und ihre internationalen Gläubiger. Erläutere Krisenmechanismus und passende Regulierung.',
   'A simplified fictional banking network has assets100, liabilities95 and equity5. Losses8 hit a bank and its international creditors. Explain the crisis mechanism and suitable regulation.',
   'Die Person erklärt aufgezehrtes Eigenkapital und negative Restgröße−3 sowie mögliche Ansteckung. Sie ordnet Verlustpuffer und Begrenzung von Verflechtungen zu, erklärt Transparenz als Hilfe und setzt zusätzliche Liquidität nicht mit behobener Überschuldung gleich.',
   'The learner explains exhausted equity and a negative remainder−3 alongside possible contagion. They match loss buffers and limits on interconnections, explain disclosure as support, and do not equate liquidity support with restored solvency.',
   'Verlustabsorption und internationale Ansteckung unterscheiden.','Distinguish loss absorption and cross-border contagion.'),
  ('short-funding-and-fire-sales','Ein zweites fiktives Netz finanziert langfristige Kredite täglich neu. Internationale Geldgeber ziehen Mittel zurück; Banken verkaufen ähnliche Wertpapiere gleichzeitig. Diskutierte Regeln betreffen Liquidität, Laufzeiten und eine Finanztransaktionssteuer. Erläutere.',
   'Another fictional network rolls over funding for long-term loans daily. International lenders withdraw; banks simultaneously sell similar securities. Proposed rules concern liquidity, maturities and a financial transaction tax. Explain them.',
   'Die Person erklärt Refinanzierungsdruck, Notverkäufe und Preisrückkopplung. Sie ordnet Liquiditäts-/Laufzeitregeln dem Mechanismus zu und diskutiert die Steuer als anders ansetzenden Ansatz, ohne ihre sichere Krisenverhinderung oder freie Märkte als automatisch effizient zu behaupten.',
   'The learner explains refinancing pressure, fire sales and price feedback. They connect liquidity and maturity rules to the mechanism and discuss the tax as a different approach without claiming guaranteed crisis prevention or automatically efficient free markets.',
   'Instrument nach Ursache statt nach Schlagwort zuordnen.','Match regulation to causes rather than slogans.')],
 [('crisis-channel','Kapitalverlust, Refinanzierung oder gemeinsame Anlagen.','Capital losses, funding or shared assets.'),('regulatory-limit','Verlustpuffer, Liquidität, Offenlegung und Ausweichreaktionen.','Loss buffers, liquidity, disclosure and avoidance responses.')])
add('Dynamics of trade conflicts','The learner can analyse protectionism–free-trade conflicts using current cases.','data',
 'Ein Handelskonflikt ist eine zeitliche Folge politischer Maßnahmen und Reaktionen mit Interessen, Rechtsbehauptungen und wirtschaftlichen Rückwirkungen. Analyse braucht ein datiertes aktuelles Material; zeitliche Folge allein belegt keine Ursache und Ankündigung ist nicht Umsetzung.',
 'A trade conflict is a sequence of policies and responses involving interests, legal claims and economic feedback. Analysis needs dated current material; temporal order alone proves no cause, and an announcement is not implementation.',
 'Die Person analysiert in neuen datierten Konfliktdossiers Akteure, Instrumente, belegte Reaktionen und Rückwirkungen, unterscheidet Behauptungen von Nachweisen und hält den aktuellen Umsetzungsstand fest.',
 'In new dated conflict dossiers, the learner analyses actors, instruments, evidenced responses and feedback, distinguishes claims from evidence, and keeps the current implementation status explicit.',
 [('tariff-retaliation-sequence','Ein aktuell datiertes Konfliktdossier liefert eine vereinfachte Abfolge: angekündigter Industriezoll, späterer Rechtsakt und angekündigte Gegenzölle auf Agrargüter. Hersteller nutzen importierte Vorprodukte. Quellen und Umsetzungstermine liegen als Material vor. Analysiere.',
   'A currently dated conflict dossier provides a simplified sequence: an announced industrial tariff, a later legal act and announced retaliatory tariffs on agricultural goods. Producers use imported inputs. Sources and implementation dates are supplied. Analyse.',
   'Die Person trennt Ankündigungen und geltende Maßnahmen, rekonstruiert Interessen und Reaktionskette und erklärt mögliche Vorprodukt- sowie Exportfolgen. Sie prüft Datierung und Gegenargumente, statt jede Absatzänderung allein dem ersten Zoll zuzuschreiben.',
   'The learner separates announcements from operative measures, reconstructs interests and responses, and explains possible input and export effects. They assess dates and counterarguments rather than attributing every sales change solely to the first tariff.',
   'Aktueller Status und Rückwirkungen in einer real zu belegenden Fallfolge.','Current status and feedback in a sequence requiring actual source evidence.'),
  ('restriction-negotiation-and-rerouting','Ein anderes aktuelles Dossier enthält datierte Exportbeschränkungen eines Vorprodukts, Verhandlungen und Ausweichbeschaffung. Transportpreise ändern sich gleichzeitig. Das Fallmaterial benennt offizielle Quellen und einen Stichtag. Analysiere den Konflikt.',
   'Another current dossier contains dated export restrictions on an input, negotiations and alternative sourcing. Transport prices change simultaneously. Materials identify official sources and a reference date. Analyse the conflict.',
   'Die Person unterscheidet politische Begrenzung, Marktanpassung und noch offene Verhandlungsergebnisse; sie erklärt Interessen, Kosten- und Abhängigkeitseffekte. Sie berücksichtigt die zusätzliche Transportpreisänderung und behauptet weder sofortige Normalisierung noch monokausale Folgen.',
   'The learner distinguishes policy restrictions, market adaptation and unresolved negotiations, explains interests, costs and dependencies, and considers the additional transport-price change. They claim neither immediate normalisation nor single-cause effects.',
   'Konfliktanalyse bei mehreren gleichzeitig wirkenden Ursachen.','Analyse a conflict with several concurrent causes.')],
 [('case-date-status','Aktueller Stichtag, offizielle Quelle und angekündigte oder tatsächlich umgesetzte Maßnahme.','Current reference date, official source and announced versus implemented action.'),('feedback-channel','Vorprodukte, Gegenzölle, Umlenkung oder Verhandlungen.','Inputs, retaliation, rerouting or negotiations.')])
add('Financial crises and regulatory mechanisms','The learner can discuss causes and countermeasures of current financial crises.','concept',
 'Aktuelle Krisen müssen anhand datierter Quellen, Bilanzen und Finanzierungsbedingungen erklärt werden. Gegenmaßnahmen zielen verschieden auf Liquidität, Verlusttragfähigkeit und Ansteckung; Wirkungen, Nebenfolgen und verbleibende Unsicherheit gehören zur Diskussion.',
 'Current crises need explanation through dated sources, balance sheets and funding conditions. Responses address liquidity, loss-bearing capacity and contagion differently; discussion includes effects, side effects and uncertainty.',
 'Die Person diskutiert in neuen aktuell belegten Krisenfällen eine ursächliche Kette und mehrere dazu passende Gegenmaßnahmen mit Bedingungen und Zielkonflikten.',
 'In newly sourced current crisis cases, the learner discusses a causal chain and several suitable responses with conditions and trade-offs.',
 [('deposit-run-and-duration','Das bereitgestellte aktuelle Krisendossier zeigt vereinfacht langfristige Wertpapiere, sinkende Marktwerte und schnelle Einlagenabzüge. Offizielle datierte Angaben zu Verlusten, Liquidität und Sicherungsregeln liegen vor. Diskutiere Ursachen und Gegenmaßnahmen.',
   'The supplied current crisis dossier shows a simplified combination of long-term securities, falling market values and rapid deposit withdrawals. Official dated information on losses, liquidity and safeguards is supplied. Discuss causes and responses.',
   'Die Person verbindet Bewertungsverluste, kurze Finanzierung und Vertrauensverlust, trennt Liquiditätsnot von Überschuldung und diskutiert Liquiditätshilfe, Kapital oder geordnete Abwicklung anhand der Fallregeln. Sie berücksichtigt Haftung und Fehlanreize statt jede Rettung als gleich wirksam darzustellen.',
   'The learner links valuation losses, short funding and lost confidence, separates illiquidity from insolvency, and discusses liquidity support, capital or orderly resolution under the supplied rules. They consider liability and incentives rather than equating all rescues.',
   'Ursache und Gegenmaßnahme bei einem datierten aktuellen Bankfall.','Causes and responses in a dated current bank case.'),
  ('shared-exposures-and-cross-border-credit','Ein anderes datiertes Krisendossier dokumentiert gemeinsame Branchenrisiken mehrerer internationaler Banken, fallende Sicherheitenwerte und Kreditkürzungen. Material gibt Stresstestannahmen, Aufsichtszuständigkeiten und mögliche Puffer frei. Diskutiere.',
   'Another dated crisis dossier documents common sector risks across international banks, falling collateral values and credit cuts. Materials provide stress assumptions, supervisory responsibilities and available buffers. Discuss.',
   'Die Person erklärt gemeinsame Verluste und mögliche Verstärkung durch Kreditkürzungen, diskutiert Puffer, gezielte Aufsicht und internationale Koordination. Sie trennt Szenario vom beobachteten Ergebnis und benennt Grenzen, statt einen Stresstest als Zukunftsprognose auszugeben.',
   'The learner explains common losses and possible amplification through credit cuts, discusses buffers, targeted supervision and international coordination, and separates scenarios from observations. They identify limits rather than presenting a stress test as a forecast.',
   'Systemische Rückkopplung und belegte statt behauptete Krisenwirkung.','Systemic feedback and evidenced rather than asserted crisis effects.')],
 [('evidence-date','Offizielle datierte Krisenangaben versus hypothetisches Stressszenario.','Official dated crisis evidence versus hypothetical stress scenarios.'),('response-target','Liquidität, Kapital, Abwicklung oder internationale Koordination.','Liquidity, capital, resolution or international coordination.')])
add('Trade-policy trade-offs','The learner can discuss distributional effects of tariff and free-trade policy.','concept',
 'Handelspolitik verteilt Vorteile und Belastungen zwischen Verbrauchern, Produzenten, Beschäftigten, Staat und Handelspartnern. Auch Zeit und Vorproduktverflechtungen zählen; gesamtwirtschaftliche und gruppenspezifische Wirkungen sind verschieden.',
 'Trade policy distributes gains and burdens among consumers, producers, workers, government and trading partners. Time and input links matter; aggregate effects differ from effects on particular groups.',
 'Die Person diskutiert neue Zoll- und Marktöffnungsfälle anhand mehrerer betroffener Gruppen, konkreter Wirkungen, Zeiträume und möglicher Ausgleichsmaßnahmen.',
 'The learner discusses new tariff and market-opening cases through several affected groups, concrete mechanisms, time horizons and possible compensation.',
 [('tariff-winners-and-input-users','Ein fiktiver Zoll schützt heimische Metallanbieter, verteuert aber Metall für Bauunternehmen und Haushalte. Material nennt Staatseinnahmen und mögliche Gegenmaßnahmen des Handelspartners. Diskutiere Verteilung.',
   'A fictional tariff protects domestic metal firms but raises costs for builders and households. Materials give government revenue and possible responses by the trading partner. Discuss distribution.',
   'Die Person trennt mögliche Anbieter- und Einnahmevorteile von Verbraucher-/Vorproduktkosten und Exportbelastungen bei Vergeltung. Sie berücksichtigt Weitergabe und Beschäftigungsbedingungen, ohne alle heimischen Firmen als Gewinner zu behandeln.',
   'The learner separates possible supplier and revenue gains from consumer/input costs and export burdens under retaliation. They consider pass-through and employment conditions without treating every domestic firm as a winner.',
   'Verteilung entlang einer Wertschöpfungskette.','Distribution along a value chain.'),
  ('market-opening-and-adjustment','Ein anderer fiktiver Markt senkt Importzölle. Verbraucher zahlen weniger; einige heimische Tätigkeiten schrumpfen, Exportchancen steigen. Material gibt Umschulungszugang und Transferkosten. Diskutiere kurz- und langfristige Verteilung.',
   'Another fictional market cuts import tariffs. Consumers pay less, some domestic activities contract and export opportunities grow. Materials give retraining access and transfer costs. Discuss short- and long-term distribution.',
   'Die Person erklärt Preisvorteile und ungleich verteilte Anpassungskosten, berücksichtigt neue Chancen mit Qualifikations- und Zeitbedingungen und prüft finanzierbaren Ausgleich. Ein aggregierter Vorteil bedeutet keinen automatisch ausgeglichenen individuellen Verlust.',
   'The learner explains price benefits and unequal adjustment costs, considers new opportunities conditional on skills and time, and examines funded compensation. Aggregate gains do not automatically compensate individual losses.',
   'Gesamtgewinn und tatsächlicher Ausgleich unterscheiden.','Distinguish aggregate gains and actual compensation.')],
 [('affected-group','Endverbraucher, Vorproduktnutzer, Beschäftigte, Staat oder Partner.','Consumers, input users, workers, government or partners.'),('adjustment-time','Unmittelbare Preiswirkung und bedingte neue Tätigkeiten.','Immediate price effects and conditional new activities.')])
add('Actors in the global financial system','The learner can compare the roles of the IMF, World Bank, private and governmental actors.','concept',
 'Internationale Finanzakteure unterscheiden sich nach Auftrag, Finanzierung und Entscheidungsrechten. IWF-Stabilitätsunterstützung und längerfristige Weltbankentwicklung ergänzen sich, während private Geldgeber und Staaten eigene Interessen und Verantwortung tragen; keine Institution ist eine Weltregierung.',
 'International financial actors differ by mandate, funding and decision rights. IMF stability support and longer-term World Bank development complement each other, while private lenders and governments have their own interests and responsibilities; no institution is a world government.',
 'Die Person vergleicht in neuen Fällen alle vier Akteursgruppen anhand ihres tatsächlichen Beitrags, Auftrags und einer entscheidenden Grenze oder Beziehung.',
 'In new cases, the learner compares all four actor groups through their contribution, mandate and a decisive limit or relationship.',
 [('payments-and-water-project','Ein fiktiver Staat hat Zahlungsbilanzprobleme und plant sichere Wasserversorgung. Material nennt IWF-Stabilitätskredit, Weltbankprojekt, private Anleihen und staatliche Budgetentscheidungen. Vergleiche Rollen, Finanzierung und Verantwortung.',
   'A fictional state has balance-of-payments problems and plans safe water supply. Materials give IMF stabilisation lending, a World Bank project, private bonds and government budget decisions. Compare roles, funding and responsibility.',
   'Die Person unterscheidet kurzfristige/mittelfristige internationale Zahlungsfähigkeit von langfristiger Entwicklung, private Rendite-/Risikointeressen und staatliche Gestaltung. Sie erklärt Ergänzung und Bedingungen, ohne IWF als normalen Projektfinanzierer oder Weltbank als Weltzentralbank darzustellen.',
   'The learner distinguishes short/medium-term international payment capacity from long-term development, private return/risk interests and government choices. They explain complementarity and conditions without treating the IMF as an ordinary project lender or World Bank as a global central bank.',
   'Vier Akteure anhand verschiedener Aufträge vergleichen.','Compare four actors through different mandates.'),
  ('debt-and-development-coordination','Ein anderes fiktives Land verhandelt mit privaten Gläubigern über Schulden. IWF beurteilt Stabilität, Weltbank unterstützt langfristige Reformen; Regierung entscheidet über den Haushalt. Material beschreibt begrenzte Mittel und Interessen. Vergleiche.',
   'Another fictional country negotiates debt with private creditors. The IMF assesses stability, World Bank supports long-term reforms and government decides the budget. Materials give limited resources and interests. Compare.',
   'Die Person vergleicht Stabilitäts-, Entwicklungs-, Gläubiger- und Regierungsrollen sowie Zusammenarbeit und Interessenkonflikte. Sie trennt Empfehlungen, Vertragsbedingungen und eigene staatliche Entscheidungen und behauptet keine automatische Entschuldung oder uneingeschränkte Verfügung einer Institution.',
   'The learner compares stability, development, creditor and government roles alongside cooperation and conflicts. They distinguish advice, contract conditions and government decisions without claiming automatic debt cancellation or unlimited institutional power.',
   'Zusammenarbeit ohne identische Zuständigkeiten.','Cooperation without identical responsibilities.')],
 [('actor-mandate','Stabilität, Entwicklung, privater Vertrag oder staatliche Entscheidung.','Stability, development, private contracts or government decisions.'),('financing-condition','Zahlungsbilanz, Projektbedarf, Schuldentragfähigkeit und Entscheidungsrechte.','Balance of payments, project needs, debt sustainability and decision rights.')])
add('Judge major trade agreements','The learner can evaluate major trade agreements and their effects.','concept',
 'Ein Handelsabkommen verbindet Marktöffnung mit Regeln, Ausnahmen und Umsetzung. Bewertung eines konkret benannten zentralen Abkommens prüft Ziel, wirtschaftliche und gesellschaftliche Wirkung sowie Betroffene und Materialstand; ein Vertragstitel beweist keine Wirkung.',
 'A trade agreement combines market access with rules, exceptions and implementation. Evaluating a named major agreement examines objectives, economic/social effects, affected groups and the material date; a treaty name establishes no outcome.',
 'Die Person bewertet in neuen Dossiers konkret benannte zentrale Handelsabkommen anhand bereitgestellter aktueller offizieller Regeltexte und Wirkungsinformationen mit einem begründeten bedingten Urteil.',
 'In new dossiers, the learner evaluates named major agreements through supplied current official rules and impact information, giving a reasoned conditional judgment.',
 [('named-agreement-access-and-rules','Ein aktuelles offizielles CETA-Dossier liefert datierte Auszüge zu Marktöffnung, Ursprungsregeln und Ausnahmen sowie Angaben für kleinere Exporteure und Verbraucher. Beurteile das konkret benannte Abkommen; sein jeweils aktueller Anwendungsstand steht im Material.',
   'A current official CETA dossier supplies dated extracts on market access, origin rules and exceptions plus information on smaller exporters and consumers. Judge the named agreement; its current application status is given in the materials.',
   'Die Person verbindet konkrete Regelungen mit Absatz-, Preis- und Durchführungseffekten, berücksichtigt kleinere Betriebe und Schutzregeln und formuliert ein kriteriales Urteil. Sie trennt vorgesehene Öffnung von nachgewiesener Nutzung und übernimmt keinen historischen Ratifikationsstand als aktuellen.',
   'The learner connects specific rules to sales, prices and implementation, considers smaller firms and safeguards, and gives a criteria-based judgment. They distinguish planned access from evidenced use and do not treat historical ratification status as current.',
   'Konkretes Abkommen nach real datiertem Material beurteilen.','Judge a specific agreement using actually dated material.'),
  ('second-named-agreement-and-outsiders','Ein zweites Dossier benennt ein weiteres zentrales Handelsabkommen, gibt offizielle datierte Zoll-/Standardregeln und Wirkungen für Mitglieder sowie Nichtmitglieder. Material zeigt unterschiedliche Produktionskosten und Zugang kleiner Anbieter. Bewerte.',
   'A second dossier names another major agreement and gives official dated tariff/standard rules and effects on members and outsiders. Materials show different production costs and access for small suppliers. Evaluate.',
   'Die Person bewertet Marktzugang und Regelkosten sowie mögliche Handelsumlenkung und Ausschlusswirkungen für Dritte. Sie hält Stichtag und tatsächliche Anwendung fest, begründet abweichende Gruppenurteile und setzt steigenden Binnenhandel nicht automatisch mit weltweitem Wohlfahrtsgewinn gleich.',
   'The learner evaluates access and compliance costs plus possible diversion and exclusion of outsiders. They keep dates and application explicit, justify different group judgments and do not equate intra-agreement trade growth with global welfare gains.',
   'Abkommen und Drittwirkungen statt bloßer Namen bewerten.','Evaluate agreements and outsider effects rather than names.')],
 [('agreement-scope','Genanntes Abkommen, konkrete Regel, Ausnahme und Anwendungsdatum.','Named agreement, specific rule, exception and application date.'),('stakeholder-effect','Kleine Exporteure, Verbraucher, Schutzinteressen und Drittländer.','Small exporters, consumers, safeguards and outsiders.')])
add('Financial instruments and derivatives','The learner can explain derivatives and their role in financial markets.','representation',
 'Ein Derivat knüpft Zahlungen an einen Basiswert oder eine vertragliche Bedingung. Absicherung und spekulative Exposition hängen von der zugrunde liegenden Position ab; Vertragspflicht, Option und Gegenparteirisiko sind verschieden. Risikotransfer beseitigt nicht jedes Risiko.',
 'A derivative links payments to an underlying asset or contractual condition. Hedging versus speculative exposure depends on the underlying position; contractual obligations, options and counterparty risk differ. Transferring risk does not eliminate every risk.',
 'Die Person erläutert neue einfache Derivate anhand ihrer Zahlungsregel und Grundposition, unterscheidet Absicherung und Spekulation und erklärt eine relevante verbleibende Risikoquelle.',
 'The learner explains new simple derivatives through their payment rule and underlying position, distinguishes hedging and speculation, and explains a remaining risk.',
 [('producer-forward','Eine fiktive Produzentin liefert100 Einheiten und vereinbart einen festen Terminverkaufspreis2,50; spätere Kassapreise können2 oder3 sein. Ein Händler ohne Produktion schließt denselben Verkauf ab. Erläutere Vertrag und Rollen.',
   'A fictional producer delivers100 units and fixes a forward sale price2.50; later spot prices may be2 or3. A trader without production enters the same sale. Explain the contract and roles.',
   'Die Person erklärt gesicherten Erlös250 für die Produzentin im vereinfachten erfüllten Vertrag, Vorteil oder entgangene Chance gegenüber200/300 am Kassamarkt. Sie unterscheidet abgesicherte Produktion von spekulativer Lieferpflicht ohne Bestand und nennt Erfüllungs-/Gegenparteirisiko.',
   'The learner explains secured revenue250 for the producer under the simplified fulfilled contract, gains or forgone opportunities versus200/300 spot revenue, distinguishes hedged production from a speculative delivery obligation without inventory, and identifies performance/counterparty risk.',
   'Gleicher Vertrag, unterschiedliche Grundposition.','The same contract with different underlying positions.'),
  ('option-versus-obligation','Eine fiktive Kaufoption erlaubt Kauf zu50 und kostet Prämie4. Der spätere Kurs ist40 oder60; Vergleichsvertrag verpflichtet zum Kauf50. Erläutere Zahlungswirkung und Rolle, ohne eine Anlageempfehlung.',
   'A fictional call permits buying at50 and costs premium4. The later price is40 or60; a comparison contract requires purchase at50. Explain payments and roles without investment advice.',
   'Die Person erklärt Optionsrecht ohne Ausübungspflicht, Nettoergebnis−4 oder6 bei vereinfachter sofortiger Bewertung und unterscheidet die Verpflichtung mit−10 oder10. Sie ordnet Absicherung oder Spekulation der Grundposition zu und nennt Prämie und Gegenparteibedingungen.',
   'The learner explains an option without an exercise obligation, net−4 or6 under simplified immediate valuation, and distinguishes the obligation with−10 or10. They classify hedging or speculation through the underlying position and identify premiums and counterparty conditions.',
   'Recht, Pflicht und Nettowirkung aus Vertragsregeln.','Rights, obligations and net effects through contract rules.')],
 [('contract','Terminverpflichtung versus Optionsrecht mit Prämie.','A forward obligation versus an option with a premium.'),('underlying-position','Reale Ware/Verbindlichkeit oder zusätzliche Marktposition.','An actual good/liability or additional market exposure.')])
add('Ecological effects of world trade','The learner can discuss ecological effects of trade patterns.','data',
 'Ökologische Handelsfolgen ergeben sich aus Herstellung, Transport, Produktionsumfang und Regeln. Entfernung allein ist keine vollständige Bilanz; Intensität pro Einheit und Gesamtbelastung können verschieden verlaufen.',
 'Ecological trade effects arise from production, transport, scale and rules. Distance alone is not a full accounting; per-unit intensity and total impact can move differently.',
 'Die Person diskutiert neue Handelsmuster anhand nachvollziehbarer Produktions-/Transportdaten, Umfang, Umweltregeln und möglicher Verlagerungen mit einem begründeten bedingten Urteil.',
 'The learner discusses new trade patterns using production/transport data, scale, environmental rules and possible displacement, giving a conditional judgment.',
 [('production-versus-distance','Für fiktive gleichwertige Güter betragen Emissionen je Einheit bei Import35 (Produktion30+Transport5), bei lokaler Herstellung71 (70+1). Material nennt gleiche Mengen, aber Wasserbelastung als offene Dimension. Diskutiere.',
   'For fictional equivalent goods, emissions per unit are35 for imports (production30+transport5) and71 locally (70+1). Materials give equal volumes but leave water impacts unresolved. Discuss.',
   'Die Person vergleicht vollständige bereitgestellte Emissionsketten und erklärt den Importvorteil in dieser Dimension trotz Transport. Sie begrenzt das Urteil auf gleiche Mengen/Systemgrenzen und verlangt Wasserdaten, statt Entfernung oder eine Emissionszahl als Gesamtumwelturteil zu nehmen.',
   'The learner compares the supplied emissions chains and explains the import advantage in this dimension despite transport. They limit the conclusion to equal volumes/boundaries and request water data rather than treating distance or one emissions number as a complete environmental judgment.',
   'Systemgrenze und andere Umweltmedien.','System boundaries and other environmental media.'),
  ('cleaner-unit-larger-volume','Ein anderes fiktives Handelsmuster senkt Belastung je Einheit von20 auf10; Umfang wächst von100 auf300 Einheiten. Ein Produktionsschritt wird in eine Region mit anderen Umweltregeln verlagert. Diskutiere.',
   'Another fictional trade pattern cuts per-unit impact20→10 while volume rises100→300. One stage moves to a region with different environmental rules. Discuss.',
   'Die Person berechnet Gesamtbelastung2000→3000, unterscheidet Effizienz und Skaleneffekt und prüft mögliche Verlagerung anhand Regeln und tatsächlicher Produktion. Sie behauptet weder sichere Entlastung durch Handel noch automatisch schlechtere Standards im Ausland.',
   'The learner calculates total impact2000→3000, distinguishes efficiency and scale, and examines displacement through rules and actual production. They claim neither guaranteed relief from trade nor automatically poorer foreign standards.',
   'Intensität, Gesamtmenge und regulatorische Bedingungen.','Intensity, scale and regulatory conditions.')],
 [('accounting-boundary','Herstellung, Transport und mehrere Umweltmedien.','Production, transport and several environmental media.'),('scale-rules','Menge, Effizienz und tatsächlich gegebene Umweltregeln.','Volume, efficiency and explicitly supplied environmental rules.')])
add('Risk management in the financial system','The learner can explain risk-management instruments, including capital requirements and stress tests.','data',
 'Eigenkapital trägt Verluste; Anforderungen begrenzen mögliche Verwundbarkeit. Stresstests untersuchen Belastbarkeit unter Annahmen und können Aufsichtsbedarf zeigen, sind aber keine sichere Prognose. Kapital und verfügbare Liquidität erfüllen verschiedene Aufgaben.',
 'Equity absorbs losses; requirements limit vulnerability. Stress tests examine resilience under assumptions and can inform supervision but are not certain forecasts. Capital and available liquidity serve different purposes.',
 'Die Person erläutert in neuen Fällen Kapitalanforderungen und Stressszenarien anhand von Verlusten, Bezugsgrößen und Annahmen und benennt unterschiedliche Kapital-/Liquiditätsgrenzen.',
 'In new cases, the learner explains capital requirements and stress scenarios through losses, reference quantities and assumptions, identifying distinct capital/liquidity limits.',
 [('equity-loss-and-buffer','Eine fiktive Bank hat Eigenkapital8 und eine ausdrücklich vereinfachte Bemessungsgrundlage100. Ein Stressfall erzeugt Verluste3 bei unveränderter Grundlage. Material legt eine didaktische Mindestanforderung6 fest. Erläutere.',
   'A fictional bank has equity8 and an explicitly simplified reference base100. A stress case causes losses3 with the base unchanged. Materials set a teaching minimum requirement6. Explain.',
   'Die Person berechnet verbleibendes Kapital5 und unterschrittene Fallanforderung6, erklärt Verlustabsorption und möglichen Aufsichtsbedarf. Sie kennzeichnet die vereinfachte Quote und den hypothetischen Stressfall, ohne6 als allgemein geltenden aktuellen Basel-Satz oder tatsächliche Prognose auszugeben.',
   'The learner calculates remaining capital5 below the case requirement6, explains loss absorption and possible supervisory action, and labels the simplified ratio and hypothetical stress. They present6 neither as a universal current Basel rate nor as a forecast.',
   'Fallbezogene Kapitalrechnung und Aussagegrenze des Stressszenarios.','Case-based capital calculations and scenario limits.'),
  ('solvent-but-short-of-cash','Eine andere fiktive Bank hat genügend Verlustpuffer, aber kurzfristige Auszahlungen15 und liquide Mittel5. Ein alternativer Stresstest ändert Abzugsannahmen und Sicherheitenwerte. Erläutere beide Instrumente und ihre Grenzen.',
   'Another fictional bank has adequate loss buffers but immediate payments15 and liquid funds5. An alternative stress test changes withdrawal assumptions and collateral values. Explain both instruments and their limits.',
   'Die Person erklärt Liquiditätslücke10 trotz Kapitalpuffer, trennt Kapitalanforderung von Zahlungsfähigkeit und zeigt, wie veränderte Szenarien andere Schwächen sichtbar machen. Sie fordert passende Liquiditätsmaßnahmen und stellt ein gutes Testergebnis nicht als Ausschluss aller Krisen dar.',
   'The learner explains a liquidity gap10 despite capital buffers, distinguishes capital requirements from payment capacity, and shows how different scenarios expose different weaknesses. They identify liquidity responses and do not treat a favourable test as excluding all crises.',
   'Mehr Kapital ersetzt nicht automatisch verfügbare Zahlungsmittel.','More capital does not automatically replace available payment funds.')],
 [('stress-assumption','Verluste, Einlagenabzüge, Sicherheiten und unveränderte/veränderte Bezugsgröße.','Losses, withdrawals, collateral and constant/changing reference bases.'),('risk-target','Verlusttragfähigkeit versus kurzfristige Liquidität.','Loss-bearing capacity versus immediate liquidity.')])
add('Evaluate bilateral and multilateral trade agreements','The learner can analyse and evaluate bilateral and multilateral trade agreements.','modeling',
 'Bilaterale und multilaterale Regeln unterscheiden sich in Reichweite, Koordination und Drittwirkungen. Marktöffnung kann effizientere Produktion fördern, aber Präferenzen können Handel umlenken. Analyse trennt Verbraucherpreise, Produktionskosten und staatliche Einnahmen.',
 'Bilateral and multilateral rules differ in scope, coordination and outsider effects. Opening can promote efficient production, but preferences can divert trade. Analysis separates consumer prices, production costs and public revenue.',
 'Die Person analysiert und bewertet in neuen Materialfällen bilaterale und multilaterale Regeloptionen nach Umfang, Kosten, Handelsschaffung/-umlenkung und begründeten Kriterien.',
 'In new cases, the learner analyses and evaluates bilateral and multilateral options through scope, costs, trade creation/diversion and justified criteria.',
 [('bilateral-opening-and-creation','Ein fiktives bilaterales Abkommen beseitigt Zoll40 auf Partnergut mit Produktionspreis90; heimisches Gut kostet120, Partnergut vorher130. Ein breiter multilateraler Vorschlag öffnet zusätzlich weitere Anbieter. Analysiere und bewerte anhand gegebener Regelkosten.',
   'A fictional bilateral agreement removes tariff40 on partner goods costing90; domestic goods cost120 and partner goods previously130. A broader multilateral option also opens other suppliers. Analyse and evaluate using supplied compliance costs.',
   'Die Person erklärt den Wechsel von heimischer Produktion120 zum Partner90 als mögliche Handelsschaffung, vergleicht Reichweite und Koordinations-/Regelkosten beider Optionen und begründet das Urteil. Sie behandelt bilaterale Öffnung nicht automatisch als weltweite Meistbegünstigung.',
   'The learner explains switching from domestic production120 to the partner90 as possible trade creation, compares scope and coordination/compliance costs, and justifies the judgment. They do not automatically equate bilateral opening with global most-favoured treatment.',
   'Produktionseffizienz, Reichweite und Vertragsform.','Production efficiency, coverage and agreement form.'),
  ('preference-and-diversion','Ein anderes fiktives Präferenzabkommen betrifft Partnergut90, Drittlandgut80 und heimisches Gut115. Vorher Zoll20 auf beide Importe: Drittland100; danach Partner90, Drittland100. Eine multilaterale Variante hebt beide Zölle auf. Analysiere und bewerte.',
   'Another fictional preference agreement involves partner goods90, outsider goods80 and domestic goods115. Initially both imports face tariff20: outsider100; afterwards partner90 and outsider100. A multilateral option removes both tariffs. Analyse and evaluate.',
   'Die Person erkennt Wechsel vom Drittland zum teureren Produzenten beim niedrigeren Verbraucherpreis, unterscheidet Handelsumlenkung, Kosten80→90 und entfallende Zolleinnahmen. Sie vergleicht mit multilateraler Öffnung und bewertet Kriterien, statt Preisfall allein als gesamten Wohlfahrtsgewinn auszugeben.',
   'The learner identifies switching from the outsider to a higher-cost producer at a lower consumer price, separates diversion, production costs80→90 and lost tariff revenue, and compares multilateral opening. They judge criteria rather than equating a price fall with total welfare gain.',
   'Niedrigerer Käuferpreis kann mit Handelsumlenkung zusammenfallen.','Lower purchaser prices can coexist with trade diversion.')],
 [('agreement-form','Zwei Partner versus breiter gemeinsamer Regelrahmen.','Two partners versus a broader shared framework.'),('welfare-components','Verbraucherpreis, Produktionskosten, Einnahmen und Drittwirkungen.','Consumer prices, production costs, revenue and outsider effects.')])
add('Protective tariffs and protectionism','The learner can evaluate effects of protective tariffs and non-tariff barriers.','concept',
 'Zölle verteuern Importe und können Einnahmen erzeugen; nichttarifäre Hemmnisse können Mengen, Zugang oder Regelkosten verändern. Wirkung und Legitimität müssen getrennt bewertet werden: eine gerechtfertigte Sicherheitsregel kann Kosten verursachen, ohne bloßer verdeckter Schutz zu sein.',
 'Tariffs raise import prices and can generate revenue; non-tariff barriers can change quantities, access or compliance costs. Effects and legitimacy require separate evaluation: justified safety rules can impose costs without being merely disguised protection.',
 'Die Person bewertet neue tarifäre und nichttarifäre Maßnahmen anhand von Wirkungen, Verteilung, Ziel und gegebenen Rechts-/Sicherheitsbedingungen.',
 'The learner evaluates new tariff and non-tariff measures through effects, distribution, objectives and supplied legal/safety conditions.',
 [('tariff-versus-free-quota-licences','Im fiktiven Fall führen Zoll10 je importierter Einheit und alternativ eine Quote zu je12 Importen und demselben Preisanstieg. Quotenlizenzen werden kostenlos vergeben. Bewerte Wirkungen und Verteilung.',
   'In a fictional case, tariff10 per unit and an alternative quota each leave12 imports and the same price increase. Quota licences are allocated free. Evaluate effects and distribution.',
   'Die Person erklärt identische begrenzte Mengen-/Preiswirkungen unter Fallannahmen, aber Zolleinnahmen120 gegenüber Knappheitsrenten bei Lizenzinhabern. Sie berücksichtigt Verbraucher und Produzenten und nennt die Vergabeform als entscheidend, statt Quote und Zoll immer als identisch zu behandeln.',
   'The learner explains equal stipulated quantity/price effects but tariff revenue120 versus scarcity rents for licence holders. They consider consumers/producers and identify allocation as decisive rather than always equating quotas and tariffs.',
   'Preiswirkung und Empfänger der Knappheitsrente unterscheiden.','Distinguish price effects and recipients of scarcity rents.'),
  ('safety-test-or-discriminatory-duplication','Ein anderes Material vergleicht notwendige gleiche Produktsicherheitsprüfung für alle Anbieter mit zusätzlicher inhaltlich identischer Prüfung nur für Importe. Daten geben Risiko, Kosten und Marktzugang. Bewerte das nichttarifäre Hemmnis.',
   'Another material compares necessary identical product-safety tests for all suppliers with an extra substantively identical test imposed only on imports. Data give risks, costs and access. Evaluate the non-tariff barrier.',
   'Die Person prüft Sicherheitsziel, Gleichbehandlung und unnötige Kosten anhand des Materials, erklärt Wettbewerbs-/Zugangseffekte und formuliert ein begründetes Urteil. Sie setzt nicht jede Norm mit Protektionismus oder jede Importregel automatisch mit Rechtswidrigkeit gleich.',
   'The learner examines safety objectives, equal treatment and unnecessary costs using the materials, explains competition/access effects, and gives a justified judgment. They equate neither every standard with protectionism nor every import rule with illegality.',
   'Legitimes Ziel und unnötige Handelsbeschränkung abwägen.','Weigh legitimate objectives and unnecessary restrictions.')],
 [('barrier-type','Abgabe, Menge, Prüfkosten oder Zugangsregel.','Charges, quantities, testing costs or access rules.'),('distribution-legitimacy','Einnahmen/Renten, Gleichbehandlung und belegtes Sicherheitsziel.','Revenue/rents, equal treatment and evidenced safety objectives.')])
add('Sanctions and trade','The learner can assess effects of economic sanctions on trading partners.','concept',
 'Sanktionen beschränken konkrete Güter, Zahlungen oder Akteure unter gegebenen Regeln. Wirkungen betreffen Zielakteure, Handelspartner und unbeteiligte Gruppen verschieden und hängen von Durchsetzung und Ausweichwegen ab. Politisches Ziel ist nicht bereits nachgewiesener Erfolg.',
 'Sanctions restrict specific goods, payments or actors under supplied rules. Effects differ for targets, trading partners and uninvolved groups and depend on enforcement and alternatives. A political objective is not already demonstrated success.',
 'Die Person schätzt neue Sanktionsfolgen anhand eines datierten Regelmaterials, betroffener Handelswege, Ausweichbedingungen und ungewollter Wirkungen begründet ein.',
 'The learner assesses new sanctions using dated rules, affected trade channels, alternative routes and unintended effects.',
 [('restricted-input-and-sender-cost','Ein datiertes fiktives Fallmaterial untersagt bestimmte Vorproduktexporte an Zielunternehmen. Material nennt knappe Ersatzlieferanten, senderseitige Exportfirmen und nachgelagerte Beschäftigte. Schätze Wirkung auf Handelspartner ein.',
   'Dated fictional materials prohibit specified input exports to targeted firms. They identify scarce alternative suppliers, exporting firms in the sender and downstream workers. Assess effects on trading partners.',
   'Die Person erklärt begrenzten Inputzugang und Produktionsdruck unter Ersatzbedingungen sowie Exportverluste und mittelbare Folgen. Sie trennt betroffene Unternehmen von allen Einwohnern und sagt ohne Wirkungsnachweis keine sichere politische Verhaltensänderung voraus.',
   'The learner explains restricted inputs and production pressure conditional on alternatives, exporting losses and indirect effects. They distinguish target firms from all residents and do not predict certain political behaviour change without evidence.',
   'Gezieltes Instrument, unterschiedliche Handelsbetroffene.','A targeted measure and different affected trading groups.'),
  ('payment-restriction-humanitarian-exception','Ein zweites datiertes Fallmaterial beschränkt Finanztransaktionen, erlaubt aber ausdrücklich bestimmte humanitäre Zahlungen. Material nennt Abwicklungsprobleme und mögliche Handelsumlenkung über Dritte. Schätze Handelsfolgen und Grenzen ein.',
   'A second dated material restricts financial transactions but explicitly permits specified humanitarian payments. It gives processing difficulties and possible trade rerouting through outsiders. Assess effects and limits.',
   'Die Person trennt erlaubte und beschränkte Vorgänge gemäß der Fallregel, erklärt dennoch mögliche Zahlungs-/Versorgungsprobleme und begrenzt Wirksamkeit bei Ausweichwegen. Sie behauptet weder überall identische Ausnahmen noch dass nominelle Ausnahmen jede praktische Nebenwirkung beseitigen.',
   'The learner separates permitted from restricted transactions under the case rules, explains possible payment/supply difficulties despite exceptions, and limits effectiveness where alternatives exist. They claim neither identical exceptions everywhere nor elimination of practical effects by formal exemptions.',
   'Regelscope, Durchführung und unbeabsichtigte Folgen.','Rule scope, implementation and unintended effects.')],
 [('sanction-channel','Güterzugang, Finanztransaktion oder ausgewählter Akteur.','Goods access, financial transactions or targeted actors.'),('implementation-limit','Ersatzlieferanten, Ausnahmen und tatsächliche Zahlungsabwicklung.','Alternative suppliers, exceptions and actual payment processing.')])
add('Banking regulation and Basel standards','The learner can explain the Basel frameworks and their effects on financial stability.','concept',
 'Basel-Regelwerke verbinden Verlusttragfähigkeit, ergänzende Liquiditäts-/Verschuldungsbegrenzungen, Aufsichtsprüfung und Offenlegung. Standards brauchen jeweilige Umsetzung in geltendes Recht; höhere Anforderungen verbessern bestimmte Puffer, garantieren aber keine risikofreie Bank.',
 'The Basel frameworks combine loss-bearing capacity, additional liquidity/leverage constraints, supervisory review and disclosure. Standards need jurisdiction-specific legal implementation; higher requirements improve certain buffers without guaranteeing risk-free banks.',
 'Die Person erläutert in neuen Materialfällen die verbundenen Basel-Regelbereiche, ihre Stabilitätsmechanismen und Grenzen unter dem bereitgestellten aktuellen Umsetzungsstand.',
 'In new material-based cases, the learner explains the connected Basel rule areas, their stability mechanisms and limits under the supplied current implementation status.',
 [('capital-supervision-disclosure','Ein vereinfachtes fiktives Material vergleicht Verlustpuffer8 und12 bei möglichen Verlusten9. Datierte Regelkarten beschreiben Mindestanforderungen, zusätzliche Aufsichtsprüfung und Offenlegung. Erläutere Stabilitätswirkungen des Basel-Rahmens.',
   'Simplified fictional materials compare loss buffers8 and12 against possible losses9. Dated rule cards describe minimum requirements, additional supervisory review and disclosure. Explain stability effects of the Basel framework.',
   'Die Person erklärt Verlusttragfähigkeit und verbleibendes Kapital−1/3, verknüpft Mindestregeln, Aufsichtsbeurteilung und Marktinformation und nennt zusätzliche Liquiditäts-/Verschuldungsgrenzen. Sie hält Regelstand und Bezugsgrößen sichtbar und verspricht keine vollständige Krisenfreiheit.',
   'The learner explains loss absorption and remaining capital−1/3, connects minimum rules, supervisory assessment and market information, and identifies further liquidity/leverage limits. They keep the rule version/reference bases explicit without promising total crisis immunity.',
   'Verbundenes Regelwerk statt eine einzige Mindestquote.','A connected framework rather than one minimum ratio.'),
  ('group-risk-and-implementation','Ein anderes Material zeigt international verbundene Banken, bei denen dieselben Eigenkapitalmittel zweimal gezählt werden. Datierte Auszüge geben konsolidierte Regeln, Aufsichtsprüfung und nationale Umsetzung vor. Erläutere.',
   'Another material shows internationally connected banks counting the same capital funds twice. Dated extracts give consolidated rules, supervisory review and national implementation. Explain.',
   'Die Person erklärt überzeichnete Verlusttragfähigkeit bei Doppelzählung, ordnet konsolidierte Aufsicht und Offenlegung dem Gruppenrisiko zu und unterscheidet internationalen Standard vom konkret geltenden Umsetzungsrecht. Sie nennt verbliebene Modell-/Verflechtungsrisiken.',
   'The learner explains overstated loss capacity under double-counting, relates consolidated supervision and disclosure to group risk, and distinguishes international standards from applicable implementing law. They identify remaining model/interconnection risks.',
   'Konsolidierung, Aufsicht und tatsächlicher Geltungsstand.','Consolidation, supervision and actual applicability.')],
 [('framework-area','Kapital, Liquidität/Verschuldung, Aufsicht und Offenlegung.','Capital, liquidity/leverage, supervision and disclosure.'),('legal-scope','Bankengruppe, internationales Regelwerk und ausdrücklich bereitgestellte Umsetzung.','Banking groups, international standards and explicitly supplied implementation.')])
add('Macroprudential instruments','The learner can explain and classify macroprudential instruments, such as the countercyclical capital buffer.','concept',
 'Makroprudenzielle Instrumente richten sich gegen Risiken des Finanzsystems insgesamt, etwa gemeinsame Kredit-/Preiszyklen. Kapitalpuffer können vor Belastungen aufgebaut und unter gegebenen Regeln freigegeben werden; Freigabe erzeugt kein neues Geld und garantiert keine zusätzliche Kreditvergabe.',
 'Macroprudential instruments address system-wide risks such as shared credit/price cycles. Buffers can be built before stress and released under supplied rules; releasing requirements creates no new money and guarantees no additional lending.',
 'Die Person erklärt neue makroprudenzielle Maßnahmen anhand eines Systemrisikos, grenzt sie von Einzelbankaufsicht ab und ordnet Puffer sowie eine alternative Maßnahme mit Wirkung und Grenze ein.',
 'The learner explains new macroprudential measures through systemic risks, distinguishes them from single-bank supervision and classifies buffers and an alternative measure with effects and limits.',
 [('boom-buffer-and-borrower-limit','Ein fiktiver Immobilienboom erzeugt gemeinsame Kreditrisiken. Material gibt einen didaktischen Zusatzpuffer2 % auf Bemessungsgrundlage1000 sowie alternativ eine Grenze für Kredit im Verhältnis zum Einkommen. Erkläre und ordne ein.',
   'A fictional housing boom creates common credit risks. Materials give a teaching additional buffer2% on reference base1000 and alternatively a loan-to-income limit. Explain and classify them.',
   'Die Person berechnet zusätzlichen Puffer20, erklärt Verlusttragfähigkeit gegenüber gemeinsamen Risiken und unterscheidet den kreditnehmerbezogenen Ansatz. Sie ordnet beide systemisch ein und kennzeichnet2 % als Fallannahme statt aktuellen universellen Satz.',
   'The learner calculates additional buffer20, explains loss capacity against common risks and distinguishes the borrower-based approach. They classify both as systemic and label2% as a case assumption rather than a universal current rate.',
   'Zwei makroprudenzielle Ansatzpunkte am gleichen Systemrisiko.','Two macroprudential approaches to the same systemic risk.'),
  ('downturn-release-and-credit','In einem zweiten fiktiven Abschwung wird ein aufgebauter Puffer20 regelgemäß freigegeben. Banken erleiden zugleich Verluste, Kreditnachfrage fällt und manche Schuldner sind nicht tragfähig. Erkläre Wirkung und Grenze.',
   'In another fictional downturn, an accumulated buffer20 is released under the supplied rules. Banks also suffer losses, loan demand falls and some borrowers are not viable. Explain effects and limits.',
   'Die Person erklärt gelockerte Kapitalanforderung und mögliche geringere Notwendigkeit zur Kreditkürzung, aber keine neue Bareinzahlung20. Sie berücksichtigt Verluste, Kreditwürdigkeit und Nachfrage und ordnet Freigabe als systemische Stabilisierung mit bedingter Wirkung ein.',
   'The learner explains reduced required capital and potentially less pressure to cut lending, but no new cash payment20. They consider losses, creditworthiness and demand and classify release as systemic stabilisation with conditional effects.',
   'Freigabe von Anforderungen und tatsächliche Kreditbedingungen.','Releasing requirements versus actual lending conditions.')],
 [('cycle-state','Gemeinsamer Aufschwung mit Risikoaufbau versus Abschwung mit Verlusten.','A common boom building risks versus a downturn with losses.'),('instrument-target','Bankkapital, Kreditnehmergrenzen und systemische Wechselwirkungen.','Bank capital, borrower limits and systemic interactions.')])
add('FinTech, crypto-assets and supervision','The learner can classify opportunities and risks of FinTech and crypto-asset applications from a supervisory perspective.','concept',
 'FinTech-Anwendungen können Abwicklung und Zugang verbessern, aber operative, Daten- und Marktrisiken erzeugen. Aufsichtliche Einordnung folgt Funktion, Rechtsnatur, Dienst und Anbieter im datierten Regelmaterial; Zulassung ist weder Preisgarantie noch Beleg, dass jede digitale Anwendung unter dieselbe Regel fällt.',
 'FinTech applications can improve processing and access but create operational, data and market risks. Supervisory classification follows function, legal nature, service and provider under dated rules; authorisation guarantees no price and does not place all digital applications under one regime.',
 'Die Person ordnet neue FinTech-/Kryptofälle anhand bereitgestellter aktueller Regeln nach Funktion und Aufsichtsscope ein, erklärt Chancen und konkrete Risiken und begrenzt die Bedeutung von Zulassung.',
 'The learner classifies new FinTech/crypto cases under supplied current rules by function and supervisory scope, explains opportunities and specific risks, and limits what authorisation establishes.',
 [('payment-app-and-crypto-custody','Ein datiertes Fallmaterial vergleicht eine regulierte Zahlungs-App mit einem Anbieter zur Verwahrung und Handel von ausdrücklich MiCA-erfassten Kryptowerten. Regelkarten nennen Zulassung, Kundentrennung, Information und sichere Abwicklung. Ordne Chancen/Risiken aufsichtrechtlich ein.',
   'Dated materials compare a regulated payment app with custody/trading of crypto-assets explicitly within MiCA. Rule cards give authorisation, client-asset separation, information and secure processing. Classify opportunities/risks from a supervisory perspective.',
   'Die Person verbindet schnellere Abwicklung und Zugang mit Funktionen, ordnet Anbieter/Dienst nach den Regelkarten zu und erklärt Verwahrungs-, Betriebs- und Marktpreisrisiken. Sie verwechselt Zulassung oder Kundentrennung nicht mit Kurs-/Renditegarantie oder identischen Rechtsregeln für beide Dienste.',
   'The learner links faster processing/access to functions, classifies providers/services through the rule cards, and explains custody, operational and price risks. They confuse neither authorisation nor separation with guaranteed prices/returns or identical legal regimes.',
   'Digitale Funktion, Dienst und Schutzumfang unterscheiden.','Distinguish digital functions, services and protection scope.'),
  ('token-function-and-claimed-approval','Ein zweites datiertes Material vergleicht einen Token, der nach bereitgestellter Rechtsdefinition ein Finanzinstrument ist, mit einem erfassten Kryptowert. Ein Werbetext behauptet aus dem Zulassungsstatus sicheren Gewinn. Ordne anhand gegebener Regeln ein.',
   'A second dated material compares a token classified as a financial instrument under the supplied definition with a covered crypto-asset. Advertising infers guaranteed gains from authorisation. Classify them using the given rules.',
   'Die Person prüft Rechtsnatur statt bloße Blockchainbezeichnung, ordnet nach den bereitgestellten jeweiligen Regeln zu und widerlegt den Gewinnschluss. Sie erklärt Informations-/Aufsichtsschutz und verbleibende Markt-/Technikrisiken; offene Klassifikationsangaben bleiben ausdrücklich offen, keine Anlageempfehlung.',
   'The learner checks legal nature rather than the blockchain label, classifies through the supplied applicable rules, and rejects the guaranteed-gain inference. They explain information/supervisory protections and remaining market/technical risks, leave missing classification facts unresolved and give no investment advice.',
   'Regelscope und Werbeversprechen fachlich trennen.','Separate regulatory scope and advertising claims.')],
 [('service-scope','Zahlung, Verwahrung, Handel und bereitgestellte Rechtsnatur.','Payments, custody, trading and supplied legal nature.'),('risk-protection','Operative-/Daten-/Marktrisiken gegenüber konkreten Schutzpflichten.','Operational/data/market risks versus specific protective duties.')])
if __name__=='__main__':m.main()
